def transform(grid):
    """Seed 2 spreads as two diagonals to the walls; 1's fill every 4th diagonal inside, from row 3."""
    c = grid[0].index(2); W = len(grid[0]); H = W
    g = [[0]*W for _ in range(H)]
    for r in range(H):
        for j in range(W):
            if r <= min(c, W-1-c) and (j == c-r or j == c+r):
                g[r][j] = 2
            elif r >= 3 and abs(j-c) <= r and (r-j) % 4 == 2:
                g[r][j] = 1
    return g
